fn format_result(m: &MatchResult, args: &Cli) -> String {
    let mut parts = Vec::new();
    let content = if args.clean {
        &m.clean
    } else {
        &m.full_line
    };
    // Filter and drop already applied before calling format.

    // For CSV output, we handle separately.

    if args.hide {
        // hide type
        if args.display {
            // need file
            if args.line {
                return format!("file: {} {}, line: {}", m.file_path, content, m.line_num);
            } else {
                return format!("file: {} {}", m.file_path, content);
            }
        } else {
            if args.line {
                return format!("{}, line: {}", content, m.line_num);
            } else {
                return format!("{}", content);
            }
        }
    } else {
        if args.display {
            if args.line {
                return format!("{}, file: {} {}, line: {}", m.typ, m.file_path, content, m.line_num);
            } else {
                return format!("{}, file: {} {}", m.typ, m.file_path, content);
            }
        } else {
            if args.line {
                return format!("{}, {}, line: {}", m.typ, content, m.line_num);
            } else {
                return format!("{}: {}", m.typ, content);
            }
        }
    }
}

fn write_csv_header(args: &Cli, writer: &mut fs::File) -> io::Result<()> {
    let header = if args.hide {
        if args.display && args.line {
            "file, line, data"
        } else if args.display {
            "file, data"
        } else if args.line {
            "line, data"
        } else {
            "data"
        }
    } else {
        if args.display && args.line {
            "content_type, file, line, data"
        } else if args.display {
            "content_type, file, data"
        } else if args.line {
            "content_type, line, data"
        } else {
            "content_type, data"
        }
    };
    writeln!(writer, "{}", header)?;
    Ok(())
}

fn write_csv_row(m: &MatchResult, args: &Cli, writer: &mut fs::File) -> io::Result<()> {
    let content = if args.clean { &m.clean } else { &m.full_line };
    let row = if args.hide {
        if args.display && args.line {
            format!("{}, {}, {}", m.file_path, m.line_num, content)
        } else if args.display {
            format!("{}, {}", m.file_path, content)
        } else if args.line {
            format!("{}, {}", m.line_num, content)
        } else {
            format!("{}", content)
        }
    } else {
        if args.display && args.line {
            format!("{}, {}, {}, {}", m.typ, m.file_path, m.line_num, content)
        } else if args.display {
            format!("{}, {}, {}", m.typ, m.file_path, content)
        } else if args.line {
            format!("{}, {}, {}", m.typ, m.line_num, content)
        } else {
            format!("{}, {}", m.typ, content)
        }
    };
    writeln!(writer, "{}", row)?;
    Ok(())
}

