                // So we should not print error for dir missing, just exit 0
            }
            // Do nothing, but still print time if needed?
        } else {
            for entry in WalkDir::new(dir_path).into_iter().filter_map(|e| e.ok()) {
                if entry.file_type().is_file() {
                    let path = entry.path();
                    // Try to read file as text
                    let content = match fs::read_to_string(path) {
                        Ok(c) => c,
                        Err(_) => {
                            if !args.ignore {
                                println!("[-] Permission denied for file: {}", path.display());
                            }
                            continue;
                        }
                    };
                    for (idx, line) in content.lines().enumerate() {
                        let line_num = idx+1;
                        let mut line_results = extract_line(line, line_num, &path.display().to_string(), &args, filter_re.as_ref(), drop_re.as_ref());
