                        all_results.append(&mut line_results);
                    }
                }
            }
        }
    } else if !args.file.is_empty() {
        // File processing
        let file_path = Path::new(&args.file);
        if !file_path.exists() {
            if !args.ignore {
                println!("[-] File not found: {}", args.file);
            }
            std::process::exit(1);
        }
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(_) => {
                if !args.ignore {
                    println!("[-] File not found: {}", args.file);
                }
                std::process::exit(1);
            }
        };
        for (idx, line) in content.lines().enumerate() {
            let line_num = idx+1;
            let mut line_results = extract_line(line, line_num, &file_path.display().to_string(), &args, filter_re.as_ref(), drop_re.as_ref());
            all_results.append(&mut line_results);
        }
    } else {
        // Stdin processing
        if !args.suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        // Use remaining stdin_lines from pos onwards
        let remaining_lines = if stdin_pos < stdin_lines.len() {
            stdin_lines[stdin_pos..].to_vec()
        } else {
            // If we already consumed all lines via read_all_stdin_lines, we have them; but if we had invalid handling that consumed some, remaining is from pos
            // However read_all_stdin_lines already consumed all stdin at startup, so for extraction we have them in stdin_lines
            // For case where we didn't have invalid file, stdin_pos is 0, so remaining is all
            stdin_lines.clone()
        };
        // If stdin_lines was empty because we read at startup but stdin was empty (no input), then remaining empty
        // For stdin, file_path is empty
        for (idx, line) in remaining_lines.iter().enumerate() {
            let line_num = idx+1;
            // Apply filter and drop etc.
            let mut line_results = extract_line(line, line_num, "", &args, filter_re.as_ref(), drop_re.as_ref());
            all_results.append(&mut line_results);
        }
    }

    // Now output results
    // If output file specified, write CSV header and rows to file, and not print to stdout (except time and Failed messages already printed)
    // If output file not specified, print formatted results to stdout

    if let Some(mut f) = output_file {
        // Write header
        if let Err(_) = write_csv_header(&args, &mut f) {}
        for r in &all_results {
            let _ = write_csv_row(r, &args, &mut f);
        }
    } else {
        for r in &all_results {
            println!("{}", format_result(r, &args));
        }
    }

    if args.time {
        println!("[*] Time elapsed: 00h:00m:00s");
    }

    std::process::exit(0);
}

