fn find_ipv6_matches(line: &str, thorough: bool) -> Vec<String> {
    // Implement broken matching as observed
    let patterns = vec![
        regex::Regex::new(r"(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}").unwrap(),
        regex::Regex::new(r"::(?:[0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4}").unwrap(),
        regex::Regex::new(r"::").unwrap(),
        regex::Regex::new(r"(?:[0-9a-fA-F]{1,4}:){1,}[0-9a-fA-F]{1,4}").unwrap(),
        regex::Regex::new(r"[0-9a-fA-F]{1,4}::[0-9a-fA-F]{1,4}").unwrap(),
    ];
    let mut res = Vec::new();
    let mut i = 0;
    let chars: Vec<char> = line.chars().collect();
    let len = line.len();
    // We'll work with byte indices but since ipv6 is ascii, char == byte
    let mut idx = 0;
    while idx < len {
        let mut matched: Option<String> = None;
        for pat in &patterns {
            if let Some(m) = pat.find(&line[idx..]) {
                if m.start() == 0 {
                    matched = Some(m.as_str().to_string());
                    break;
                }
            }
        }
        if let Some(m) = matched {
            res.push(m.clone());
            if !thorough {
                break;
            }
            idx += m.len();
        } else {
            idx += 1;
        }
    }
    res
}

