fn find_phone_matches(line: &str, thorough: bool) -> Vec<(String,String)> {
    // Returns Vec of (clean, full)
    let mut res = Vec::new();
    // Use PHONE_RE which captures optional prefix
    // We need to find matches where full includes prefix but clean is just NPA-NXX-XXXX
    // The original clean for +1-555-123-4567 is 555-123-4567
    // So we need to extract.
    let re_full = Regex::new(r"(?:\+?1[- ])?(?:[2-9][0-9]{2}-[0-9]{3}-[0-9]{4})").unwrap();
    // Actually to get full with prefix, we need to match prefix + number
    // Let's define re that matches optional +?1[- ]? then number
    let re = Regex::new(r"(\+?1[- ])?([2-9][0-9]{2}-[0-9]{3}-[0-9]{4})").unwrap();
    for mat in re.find_iter(line) {
        let full = mat.as_str().to_string();
        // clean is group 2
        if let Some(caps) = re.captures(&full) {
            let clean = caps.get(2).unwrap().as_str().to_string();
            res.push((clean, full));
        } else {
            res.push((full.clone(), full.clone()));
        }
        if !thorough { break; }
    }
    res
}

