fn find_url_matches(line: &str, thorough: bool) -> Vec<String> {
    let mut res = Vec::new();
    for mat in URL_RE.find_iter(line) {
        let mut s = mat.as_str().to_string();
        // Original trims trailing punctuation like . and , ?
        // From observed: "Visit https://example.com." gave https://example.com (without dot)
        // So trim trailing . , ) etc
        while s.ends_with('.') || s.ends_with(',') || s.ends_with(')') || s.ends_with(']') {
            s.pop();
        }
        // Also original for https://example.com:8080/path gave https://example.com (without port/path after colon? Actually it gave https://example.com, dropping port)
        // Let's check: input https://example.com:8080/path gave https://example.com (no port)
        // So regex should stop at colon port? But then "https://example.com/path?x=1" kept path and query.
        // The observed for :8080 case: it returned https://example.com (without :8080/path). So maybe regex stops before colon?
        // However for query string it kept. So colon port is trimmed?
        // Let's attempt to handle: if url contains colon after domain and before slash, trim from colon?
        // Actually https://example.com:8080/path -> domain is example.com, then :8080/path. If we trim from colon, we get https://example.com
        // But what about https://example.com:8080 (no path)? Should also trim?
        // Let's implement: find "://" then find next "/"; if before "/" there is ":", trim from ":".
        // Simpler: we can attempt to parse and remove port.
        // For now, mimic: if url contains ":8080" style, remove ":<digits>" and following path? But then path also removed? In observed, path was also removed for :8080 case: input https://example.com:8080/path gave https://example.com (not https://example.com/path). So port removal also removes path.
        // So we will: if url contains "://", then after "://", find ':'; if ':' before first '/' or no '/', then truncate at ':'.
        // Let's do.

        // Find after scheme
        if let Some(idx) = s.find("://") {
            let after = &s[idx+3..];
            // Find colon
            if let Some(colon_pos) = after.find(':') {
                // Find slash after colon?
                let slash_pos = after.find('/').unwrap_or(usize::MAX);
                if colon_pos < slash_pos {
                    // truncate
                    let trunc_at = idx+3+colon_pos;
                    s = s[..trunc_at].to_string();
                }
            }
        }

        res.push(s);
        if !thorough { break; }
    }
    res
}

fn find_credit_matches(line: &str, thorough: bool) -> Vec<String> {
    let mut res = Vec::new();
    // Original matches 16+ etc but we saw amex 15 didn't match
    // So it only matches 16 digits (or 16 with separators)
    // Let's use regex that matches 16 digits optionally separated by space or dash, grouped as 4-4-4-4 or continuous
    // For simplicity, use pattern r"\b(?:\d[ -]*?){16}\b" but need to ensure 13-16? Original matched 16 only? Let's test 13, 15, etc.
    // From earlier: 378282246310005 (15) didn't match, so 15 not matched.
    // 411111111111111 (15) didn't match, 41111111111111111 (17) didn't match, so only 16?
    // But credit card can be 13-16, but original seems to only match 16? Let's check: we had 4111111111111111 match, 5500000000000004 match, 6011111111111117 match, 1234567890123456 match, 0000000000000000 match, 4111-1111-1111-1111 match, 4111 1111 1111 1111 match. All 16.
    // 378282246310005 (amex 15) didn't match, so they only support 16.
    // We'll implement regex for 16 digits with optional separators: r"\b(?:\d[ -]*?){13,19}\b" but filter length after stripping separators =16
    let re = Regex::new(r"\b(?:\d[ -]*){16}\b").unwrap();
    for mat in re.find_iter(line) {
        let s = mat.as_str().to_string();
        // Count digits
        let digits: String = s.chars().filter(|c| c.is_ascii_digit()).collect();
        if digits.len() == 16 {
            res.push(s.trim().to_string());
        }
        if !thorough { break; }
    }
    res
}

