fn find_files_matches(line: &str, thorough: bool) -> Vec<String> {
    let mut res = Vec::new();
    // Use FILE_RE which captures filename
    // The file regex in original seems to match filenames with certain extensions, extracting basename.
    // Our FILE_RE captures group 1 as filename.
    for cap in FILE_RE.captures_iter(line) {
        if let Some(m) = cap.get(1) {
            res.push(m.as_str().to_string());
        } else if let Some(m) = cap.get(0) {
            res.push(m.as_str().to_string());
        }
        if !thorough { break; }
    }
    // If no match via FILE_RE, try simpler?
    // Also need to handle "my document.pdf" etc – our regex should capture.
    res
}

