#[derive(Debug)]
struct Cli {
    file: String,
    add: String,
    update: String,
    remove: String,
    list: bool,
    clean: bool,
    directory: String,
    ignore: bool,
    line: bool,
    thorough: bool,
    display: bool,
    suppress: bool,
    drop: String,
    filter: String,
    hide: bool,
    output: String,
    time: bool,
    email: bool,
    phone: bool,
    hash: bool,
    ip_addr: bool,
    ipv6_addr: bool,
    mac_addr: bool,
    credit_card: bool,
    url: bool,
    files: bool,
    bitcoin: bool,
    aws: bool,
    google: bool,
    dns: bool,
    social: bool,
    help: bool,
    version: bool,
}

fn parse_cli() -> Cli {
    let args: Vec<String> = std::env::args().collect();
    let mut cli = Cli {
        file: "".to_string(),
        add: "".to_string(),
        update: "".to_string(),
        remove: "".to_string(),
        list: false,
        clean: false,
        directory: "".to_string(),
        ignore: false,
        line: false,
        thorough: false,
        display: false,
        suppress: false,
        drop: "".to_string(),
        filter: "".to_string(),
        hide: false,
        output: "".to_string(),
        time: false,
        email: false,
        phone: false,
        hash: false,
        ip_addr: false,
        ipv6_addr: false,
        mac_addr: false,
        credit_card: false,
        url: false,
        files: false,
        bitcoin: false,
        aws: false,
        google: false,
        dns: false,
        social: false,
        help: false,
        version: false,
    };
    let mut i=1;
    while i<args.len() {
        let a = args[i].as_str();
        match a {
            "-f" | "--file" => { if i+1<args.len() { cli.file=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--file=") => { cli.file=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--add" => { if i+1<args.len() { cli.add=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--add=") => { cli.add=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--update" => { if i+1<args.len() { cli.update=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--update=") => { cli.update=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--remove" => { if i+1<args.len() { cli.remove=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--remove=") => { cli.remove=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--list" => cli.list=true,
            "-C" | "--clean" => cli.clean=true,
            "--directory" => { if i+1<args.len() { cli.directory=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--directory=") => { cli.directory=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--ignore" => cli.ignore=true,
            "-l" | "--line" => cli.line=true,
            "-T" | "--thorough" => cli.thorough=true,
            "-D" | "--display" => cli.display=true,
            "-S" | "--suppress" => cli.suppress=true,
            "--drop" => { if i+1<args.len() { cli.drop=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--drop=") => { cli.drop=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "--filter" => { if i+1<args.len() { cli.filter=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--filter=") => { cli.filter=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            "-X" | "--hide" => cli.hide=true,
            "-o" | "--output" => { if i+1<args.len() { cli.output=args[i+1].clone(); i+=1; } }
            s if s.starts_with("--output=") => { cli.output=s.splitn(2,'=').nth(1).unwrap_or("").to_string(); }
            s if s.starts_with("-o") && s.len()>2 => { cli.output=s[2..].to_string(); }
            "-t" | "--time" => cli.time=true,
            "-e" | "--email" => cli.email=true,
            "-p" | "--phone" => cli.phone=true,
            "-H" | "--hash" => cli.hash=true,
            "-i" | "--ip-addr" => cli.ip_addr=true,
            "-6" | "--ipv6-addr" => cli.ipv6_addr=true,
            "-m" | "--mac-addr" => cli.mac_addr=true,
            "-c" | "--credit-card" => cli.credit_card=true,
            "-u" | "--url" => cli.url=true,
            "-F" | "--files" => cli.files=true,
            "-b" | "--bitcoin" => cli.bitcoin=true,
            "-a" | "--aws" => cli.aws=true,
            "-g" | "--google" => cli.google=true,
            "-d" | "--dns" => cli.dns=true,
            "-s" | "--social" => cli.social=true,
            "-h" | "--help" => cli.help=true,
            "-V" | "--version" => cli.version=true,
            _ => {
                eprintln!("error: unexpected argument '{}' found", a);
                eprintln!("\nUsage: executable [OPTIONS]\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
        i+=1;
    }
    cli
}

fn plugin_path() -> PathBuf {
    let home = std::env::var("HOME").expect("Home directory not found. Failed to read environmental variable: `HOME`.");
    Path::new(&home).join(".DataSurgeon").join("plugins.json")
}

static EMAIL_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}").unwrap());
static PHONE_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"(\+?1[- ])?([2-9][0-9]{2}-[0-9]{3}-[0-9]{4})").unwrap());
static IP_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\.(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\.(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\.(?:25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\b").unwrap());
static MAC_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(?:[0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}\b").unwrap());
static URL_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"https?://[^\s/$.?#].[^\s]*").unwrap());
static CREDIT_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(?:\d[ -]*){16}\b").unwrap());
static SSN_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b\d{3}-\d{2}-\d{4}\b").unwrap());
static HASH_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b[0-9a-fA-F]{32}\b|\b[0-9a-fA-F]{40}\b|\b[0-9a-fA-F]{64}\b|\b[0-9a-fA-F]{96}\b|\b[0-9a-fA-F]{128}\b|\b[0-9a-fA-F]{16}\b").unwrap());
static BTC_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b[13][a-km-zA-HJ-NP-Z1-9]{25,34}\b").unwrap());
static AWS_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"aws_(?:access_key_id|secret_access_key)\s*=\s*[A-Za-z0-9/+=_]{16,}").unwrap());
static GOOGLE_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r#""private_key_id"\s*:\s*"[0-9a-fA-F]{40}""#).unwrap());
static FILE_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"(?i)(?:[A-Za-z]:\\|\/)?(?:[\w\-\s\\/]*\/)*([\w\-\s]+\.(?:txt|pdf|doc|xls|zip|tar|gz|rar|exe|dll|jpg|jpeg|png|gif|bmp|js|json|xml|yaml|ini|cfg|conf|log|bak|sql|db|py|sh|bat|ps1|rb))").unwrap());

fn ipv6_patterns() -> Vec<Regex> {
    vec![
        Regex::new(r"(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"::(?:[0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"::").unwrap(),
        Regex::new(r"(?:[0-9a-fA-F]{1,4}:){1,}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"[0-9a-fA-F]{1,4}::[0-9a-fA-F]{1,4}").unwrap(),
    ]
}

fn find_ipv6(line: &str, thorough: bool) -> Vec<String> {
    let patterns = ipv6_patterns();
    let mut res = Vec::new();
    let mut idx = 0;
    let len = line.len();
    while idx < len {
        let mut matched: Option<String> = None;
        for pat in &patterns {
            if let Some(m) = pat.find(&line[idx..]) {
                if m.start()==0 {
                    matched = Some(m.as_str().to_string());
                    break;
                }
            }
        }
        if let Some(m) = matched {
            res.push(m.clone());
            if !thorough { break; }
            idx += m.len();
            if idx==0 { idx+=1; }
        } else {
            idx+=1;
        }
    }
    res
}

fn find_email(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in EMAIL_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} }
    v
}
fn find_phone(line: &str, thorough: bool) -> Vec<(String,String)> {
    let re = Regex::new(r"(\+?1[- ])?([2-9][0-9]{2}-[0-9]{3}-[0-9]{4})").unwrap();
    let mut v=Vec::new();
    for m in re.find_iter(line) {
        let full = m.as_str().to_string();
        if let Some(caps) = re.captures(&full) {
            let clean = caps.get(2).unwrap().as_str().to_string();
            v.push((clean, full));
        } else {
            v.push((full.clone(), full));
        }
        if !thorough {break;}
    }
    v
}
fn find_ip(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in IP_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} }
    v
}
fn find_mac(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in MAC_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_url(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in URL_RE.find_iter(line) {
        let mut s=m.as_str().to_string();
        while s.ends_with('.') || s.ends_with(',') || s.ends_with(')') || s.ends_with(']') { s.pop(); }
        // handle port case: if after :// there is : before /, truncate at :
        if let Some(scheme_idx)=s.find("://") {
            let after=&s[scheme_idx+3..];
            if let Some(colon_pos)=after.find(':') {
                let slash_pos=after.find('/').unwrap_or(usize::MAX);
                if colon_pos<slash_pos {
                    s = s[..scheme_idx+3+colon_pos].to_string();
                }
            }
        }
        v.push(s);
        if !thorough {break;}
    }
    v
}
fn find_credit(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in CREDIT_RE.find_iter(line) {
        let s=m.as_str().to_string();
        let digits: String=s.chars().filter(|c| c.is_ascii_digit()).collect();
        if digits.len()==16 { v.push(s.trim().to_string()); if !thorough {break;} }
    }
    v
}
fn find_hash(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in HASH_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_btc(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in BTC_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_aws(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in AWS_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_google(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in GOOGLE_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_files(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for cap in FILE_RE.captures_iter(line) {
        if let Some(g)=cap.get(1) { v.push(g.as_str().to_string()); } else if let Some(g)=cap.get(0) { v.push(g.as_str().to_string()); }
        if !thorough {break;}
    }
    v
}
fn find_ssn(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in SSN_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }

