                };
                if !enabled { continue; }
                let matches = func(line, true);
                // Apply filter and drop for clean
                for m in matches {
                    if let Some(f)=filter_re {
                        if !f.is_match(&m) { continue; }
                    }
                    if let Some(d)=drop_re {
                        if d.is_match(&m) { continue; }
