                    "social_security" => cli.social || all,
                    _ => false,
                };
                if !enabled { continue; }

                // For phone, we need full and clean
                if *typ=="phone_number" {
                    let matches = find_phone(line, true);
                    for (clean, full) in matches {
                        // drop check for clean
                        if let Some(d)=drop_re {
                            if d.is_match(&clean) { continue; }
                        }
                        if line_matches_drop {
                            // only clean
                            results.push(OutputItem {
                                typ: *typ,
                                data: clean.clone(),
                                file_path: file_path.to_string(),
                                line_num,
