                            results.push(OutputItem {
                                typ: *typ,
                                data: clean.clone(),
                                file_path: file_path.to_string(),
                                line_num,
                            });
                        }
                    }
                } else {
                    let matches = func(line, true);
                    for m in matches {
                        if let Some(d)=drop_re {
                            if d.is_match(&m) { continue; }
                        }
                        if line_matches_drop {
                            results.push(OutputItem {
                                typ: *typ,
                                data: m.clone(),
                                file_path: file_path.to_string(),
                                line_num,
                            });
                        } else {
                            results.push(OutputItem {
                                typ: *typ,
                                data: line.to_string(),
                                file_path: file_path.to_string(),
                                line_num,
                            });
                            results.push(OutputItem {
                                typ: *typ,
                                data: m.clone(),
                                file_path: file_path.to_string(),
                                line_num,
                            });
                        }
                    }
                }
            }
        } else {
            // NC without T
            // If line_matches_drop, fallback to clean as per earlier
            if line_matches_drop {
                // fallback to clean of first type that has surviving clean match
                for (typ, func) in help_order.iter() {
                    let enabled = match *typ {
                        "email" => cli.email || all,
                        "phone_number" => cli.phone || all,
                        "hashes" => cli.hash || all,
                        "ip_address" => cli.ip_addr || all,
                        "ipv6_address" => cli.ipv6_addr || all,
                        "mac_address" => cli.mac_addr || all,
                        "credit_card" => cli.credit_card || all,
                        "url" => cli.url || all,
                        "files" => cli.files || all,
                        "bitcoin_wallet" => cli.bitcoin || all,
                        "aws_keys" => cli.aws || all,
                        "google" => cli.google || all,
                        "dns" => cli.dns || all,
                        "social_security" => cli.social || all,
                        _ => false,
                    };
                    if !enabled { continue; }
                    if *typ=="phone_number" {
                        let matches=find_phone(line, false);
                        for (clean,_full) in matches {
                            if let Some(d)=drop_re {
                                if d.is_match(&clean) { continue; }
                            }
                            results.push(OutputItem {
                                typ: *typ,
                                data: clean,
                                file_path: file_path.to_string(),
                                line_num,
                            });
                            break;
                        }
                    } else {
                        let matches=func(line,false);
                        for m in matches {
                            if let Some(d)=drop_re {
                                if d.is_match(&m) { continue; }
                            }
                            results.push(OutputItem {
                                typ: *typ,
                                data: m,
                                file_path: file_path.to_string(),
                                line_num,
                            });
                            break;
                        }
                    }
                    if !results.is_empty() { break; }
                }
            } else {
                // Normal NC without T: first type that has matches, output full line once
                for (typ, func) in help_order.iter() {
                    let enabled = match *typ {
                        "email" => cli.email || all,
                        "phone_number" => cli.phone || all,
                        "hashes" => cli.hash || all,
                        "ip_address" => cli.ip_addr || all,
                        "ipv6_address" => cli.ipv6_addr || all,
                        "mac_address" => cli.mac_addr || all,
                        "credit_card" => cli.credit_card || all,
                        "url" => cli.url || all,
                        "files" => cli.files || all,
                        "bitcoin_wallet" => cli.bitcoin || all,
                        "aws_keys" => cli.aws || all,
                        "google" => cli.google || all,
                        "dns" => cli.dns || all,
                        "social_security" => cli.social || all,
                        _ => false,
                    };
                    if !enabled { continue; }
                    let matches = if *typ=="phone_number" {
                        let pm=find_phone(line,false);
                        if pm.is_empty() { Vec::new() } else { vec!["".to_string()] }
                    } else {
                        func(line,false)
                    };
                    if !matches.is_empty() {
                        // Check drop for full line? Already checked line_matches_drop false, so full line does not match drop
                        results.push(OutputItem {
                            typ: *typ,
                            data: line.to_string(),
                            file_path: file_path.to_string(),
                            line_num,
                        });
                        break;
                    }
                }
            }
        }
    }

    results
}
RS
