fn ipv6_patterns() -> Vec<Regex> {
    vec![
        Regex::new(r"(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"::(?:[0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"::").unwrap(),
        Regex::new(r"(?:[0-9a-fA-F]{1,4}:){1,}[0-9a-fA-F]{1,4}").unwrap(),
        Regex::new(r"[0-9a-fA-F]{1,4}::[0-9a-fA-F]{1,4}").unwrap(),
    ]
}

fn find_ipv6(line: &str, thorough: bool) -> Vec<String> {
    let patterns = ipv6_patterns();
    let mut res = Vec::new();
    let mut idx = 0;
    let len = line.len();
    while idx < len {
        let mut matched: Option<String> = None;
        for pat in &patterns {
            if let Some(m) = pat.find(&line[idx..]) {
                if m.start()==0 {
                    matched = Some(m.as_str().to_string());
                    break;
                }
            }
        }
        if let Some(m) = matched {
            res.push(m.clone());
            if !thorough { break; }
            idx += m.len();
            if idx==0 { idx+=1; }
        } else {
            idx+=1;
        }
    }
    res
}

fn find_email(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in EMAIL_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} }
    v
}
fn find_phone(line: &str, thorough: bool) -> Vec<(String,String)> {
    let re = Regex::new(r"(\+?1[- ])?([2-9][0-9]{2}-[0-9]{3}-[0-9]{4})").unwrap();
    let mut v=Vec::new();
    for m in re.find_iter(line) {
        let full = m.as_str().to_string();
        if let Some(caps) = re.captures(&full) {
            let clean = caps.get(2).unwrap().as_str().to_string();
            v.push((clean, full));
        } else {
            v.push((full.clone(), full));
        }
        if !thorough {break;}
    }
    v
}
fn find_ip(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
