                                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                                print!("[+] Do you want to exit? (y/n): ");
                                io::stdout().flush().unwrap();
                                let res = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                                match res {
                                    PromptResult::Yes => std::process::exit(1),
                                    PromptResult::No => { /* continue to fetch */ },
                                    PromptResult::Invalid => {
                                        // For add, invalid input handling loops? But we will cause overflow if needed
                                        // We'll loop until valid, causing overflow if exhausted
                                        loop {
                                            println!("[-] Invalid input. Please enter 'y' or 'n'.");
                                            print!("[+] Do you want to exit? (y/n): ");
                                            io::stdout().flush().unwrap();
                                            let res2 = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                                            match res2 {
                                                PromptResult::Yes => std::process::exit(1),
                                                PromptResult::No => break,
                                                PromptResult::Invalid => {
                                                    if prompt_pos >= stdin_lines_vec.len() {
                                                        fn overflow() { overflow() }
                                                        overflow();
                                                    }
                                                    continue;
                                                }
                                            }
                                        }
                                    }
