                                                fn overflow() { overflow() }
                                                overflow();
                                            }
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            Err(_) => {
                // missing already printed
            }
        }

        // Now fetch
        let trimmed = add_url.trim_end_matches('/');
        let without_prefix = if trimmed.starts_with("https://github.com/") {
            &trimmed["https://github.com/".len()..]
        } else if trimmed.starts_with("http://github.com/") {
            &trimmed["http://github.com/".len()..]
        } else {
            trimmed
        };
        let raw_url = format!("https://raw.githubusercontent.com/{}/main/plugins.json", without_prefix);
        let client = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_secs(10))
            .build()
            .unwrap();
        match client.get(&raw_url).send() {
            Ok(resp) => {
                match resp.text() {
                    Ok(txt) => {
                        if let Ok(_) = serde_json::from_str::<serde_json::Value>(&txt) {
                            // success, add
                            std::process::exit(0);
                        } else {
                            eprintln!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: failed to parse");
                            std::process::exit(1);
                        }
                    }
                    Err(e) => {
                        eprintln!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}", e);
                        std::process::exit(1);
                    }
                }
            }
            Err(e) => {
                eprintln!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Extraction handling: check invalid file again
    if !file_missing_startup {
        if let Ok(content) = fs::read_to_string(&ppath) {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&content) {
                if let Some(arr) = v.as_array() {
                    if !arr.is_empty() {
                        // invalid
                        println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                        print!("[+] Do you want to exit? (y/n): ");
                        io::stdout().flush().unwrap();
                        let res = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                        match res {
                            PromptResult::Yes => std::process::exit(1),
                            PromptResult::No => {},
                            PromptResult::Invalid => {
                                loop {
                                    println!("[-] Invalid input. Please enter 'y' or 'n'.");
                                    print!("[+] Do you want to exit? (y/n): ");
                                    io::stdout().flush().unwrap();
                                    let res2 = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                                    match res2 {
                                        PromptResult::Yes => std::process::exit(1),
                                        PromptResult::No => break,
                                        PromptResult::Invalid => {
                                            // cause overflow if needed
                                            if prompt_pos >= stdin_lines_vec.len() {
                                                fn overflow() { overflow() }
                                                overflow();
                                            }
                                            continue;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                print!("[+] Do you want to exit? (y/n): ");
                io::stdout().flush().unwrap();
                let res = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                match res {
                    PromptResult::Yes => std::process::exit(1),
                    PromptResult::No => {},
                    PromptResult::Invalid => {
                        loop {
                            println!("[-] Invalid input. Please enter 'y' or 'n'.");
                            print!("[+] Do you want to exit? (y/n): ");
                            io::stdout().flush().unwrap();
                            let res2 = read_prompt(&mut stdin_lines_vec, &mut prompt_pos);
                            match res2 {
                                PromptResult::Yes => std::process::exit(1),
                                PromptResult::No => break,
                                PromptResult::Invalid => {
                                    if prompt_pos >= stdin_lines_vec.len() {
                                        fn overflow() { overflow() }
                                        overflow();
                                    }
                                    continue;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Prepare regexes
    let filter_re: Option<Regex> = if cli.filter.is_empty() { None } else { Some(Regex::new(&cli.filter).unwrap()) };
    let drop_re: Option<Regex> = if cli.drop.is_empty() { None } else { Some(Regex::new(&cli.drop).unwrap()) };

    // Output file handling
    let mut output_file: Option<fs::File> = None;
    if !cli.output.is_empty() {
        let f = fs::OpenOptions::new().create(true).append(true).open(&cli.output).unwrap();
        output_file = Some(f);
    }

    let mut results: Vec<OutputItem> = Vec::new();

    if !cli.directory.is_empty() {
        let dir_path = Path::new(&cli.directory);
        if !dir_path.exists() {
            // No error, exit 0
        } else {
            for entry in WalkDir::new(dir_path).into_iter().filter_map(|e| e.ok()) {
                if entry.file_type().is_file() {
                    let p = entry.path();
                    let content = match fs::read_to_string(p) {
                        Ok(c) => c,
                        Err(_) => {
                            if !cli.ignore {
                                println!("[-] Permission denied for file: {}", p.display());
                            }
                            continue;
                        }
                    };
                    for (idx, line) in content.lines().enumerate() {
                        let mut r = process_line(line, idx+1, &p.display().to_string(), &cli, filter_re.as_ref(), drop_re.as_ref());
                        results.append(&mut r);
                    }
                }
            }
        }
    } else if !cli.file.is_empty() {
        let file_path = Path::new(&cli.file);
        if !file_path.exists() {
            if !cli.ignore {
                println!("[-] File not found: {}", cli.file);
            }
            std::process::exit(1);
        }
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(_) => {
                if !cli.ignore {
                    println!("[-] File not found: {}", cli.file);
                }
                std::process::exit(1);
            }
        };
        for (idx, line) in content.lines().enumerate() {
            let mut r = process_line(line, idx+1, &file_path.display().to_string(), &cli, filter_re.as_ref(), drop_re.as_ref());
            results.append(&mut r);
        }
    } else {
        if !cli.suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        // remaining stdin lines from prompt_pos
        let remaining = if prompt_pos < stdin_lines_vec.len() {
            stdin_lines_vec[prompt_pos..].to_vec()
        } else {
            vec![]
        };
        // If we read all stdin at startup, we have remaining. If prompt consumed some, we use from pos
        for (idx, line) in remaining.iter().enumerate() {
            let mut r = process_line(line, idx+1, "", &cli, filter_re.as_ref(), drop_re.as_ref());
            results.append(&mut r);
        }
    }

    if let Some(mut f) = output_file {
        // write header
        let header = if cli.hide {
            if cli.display && cli.line { "file, line, data" }
            else if cli.display { "file, data" }
            else if cli.line { "line, data" }
            else { "data" }
        } else {
            if cli.display && cli.line { "content_type, file, line, data" }
            else if cli.display { "content_type, file, data" }
            else if cli.line { "content_type, line, data" }
            else { "content_type, data" }
        };
        writeln!(f, "{}", header).unwrap();
        for r in &results {
            let row = if cli.hide {
                if cli.display && cli.line { format!("{}, {}, {}", r.file_path, r.line_num, r.data) }
                else if cli.display { format!("{}, {}", r.file_path, r.data) }
                else if cli.line { format!("{}, {}", r.line_num, r.data) }
                else { format!("{}", r.data) }
            } else {
                if cli.display && cli.line { format!("{}, {}, {}, {}", r.typ, r.file_path, r.line_num, r.data) }
                else if cli.display { format!("{}, {}, {}", r.typ, r.file_path, r.data) }
                else if cli.line { format!("{}, {}, {}", r.typ, r.line_num, r.data) }
                else { format!("{}, {}", r.typ, r.data) }
            };
            writeln!(f, "{}", row).unwrap();
        }
    } else {
        for r in &results {
            println!("{}", format_output(r, &cli));
        }
    }

    if cli.time {
        println!("[*] Time elapsed: 00h:00m:00s");
    }
}

enum PromptResult { Yes, No, Invalid }

fn read_prompt(lines: &mut Vec<String>, pos: &mut usize) -> PromptResult {
    if *pos >= lines.len() {
        // Try reading from actual stdin
        let mut s = String::new();
        let read = io::stdin().read_line(&mut s);
        match read {
            Ok(0) => return PromptResult::Invalid,
            Ok(_) => {
                let t = s.trim();
                if t=="y" { return PromptResult::Yes; }
                else if t=="n" { return PromptResult::No; }
                else { return PromptResult::Invalid; }
            }
            Err(_) => return PromptResult::Invalid,
        }
    }
    let line = lines[*pos].trim().to_string();
    *pos+=1;
    if line=="y" { PromptResult::Yes }
    else if line=="n" { PromptResult::No }
    else { PromptResult::Invalid }
}

fn handle_invalid_for_list(ppath: &Path, lines: &mut Vec<String>, pos: &mut usize) -> ! {
    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
    print!("[+] Do you want to exit? (y/n): ");
    io::stdout().flush().unwrap();
    let mut attempt=0;
    loop {
        let res = read_prompt(lines, pos);
        match res {
            PromptResult::Yes => std::process::exit(1),
            PromptResult::No => {
                if attempt==0 {
                    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                    print!("[+] Do you want to exit? (y/n): ");
                    io::stdout().flush().unwrap();
                    attempt+=1;
                    continue;
                } else {
                    println!("No plugins found. Plugin File: {}", ppath.display());
                    std::process::exit(1);
                }
            }
            PromptResult::Invalid => {
                println!("[-] Invalid input. Please enter 'y' or 'n'.");
                print!("[+] Do you want to exit? (y/n): ");
                io::stdout().flush().unwrap();
                if *pos>=lines.len() {
                    fn overflow() { overflow() }
                    overflow();
                }
                continue;
            }
        }
    }
}

