fn format_output(r: &OutputItem, cli: &Cli) -> String {
    if cli.hide {
        if cli.display {
            if cli.line {
                format!("file: {} {}, line: {}", r.file_path, r.data, r.line_num)
            } else {
                format!("file: {} {}", r.file_path, r.data)
            }
        } else {
            if cli.line {
                format!("{}, line: {}", r.data, r.line_num)
            } else {
                format!("{}", r.data)
            }
        }
    } else {
        if cli.display {
            if cli.line {
                format!("{}, file: {} {}, line: {}", r.typ, r.file_path, r.data, r.line_num)
            } else {
                format!("{}, file: {} {}", r.typ, r.file_path, r.data)
            }
        } else {
            if cli.line {
                format!("{}, {}, line: {}", r.typ, r.data, r.line_num)
            } else {
                format!("{}: {}", r.typ, r.data)
            }
        }
    }
}

fn process_line(line: &str, line_num: usize, file_path: &str, cli: &Cli, filter_re: Option<&Regex>, drop_re: Option<&Regex>) -> Vec<OutputItem> {
    let mut results = Vec::new();

    let any_flag = cli.email || cli.phone || cli.hash || cli.ip_addr || cli.ipv6_addr || cli.mac_addr || cli.credit_card || cli.url || cli.files || cli.bitcoin || cli.aws || cli.google || cli.dns || cli.social;
    let all = !any_flag;

    // Collect matches per type in order that attempts to mimic original's broken order for thorough?
    // For simplicity, we will collect in order: Email, Phone, Hash, Ip, Ipv6, Mac, Credit, Url, Files, Bitcoin, Aws, Google, Dns, Social
    // But for NC without thorough, we output only first matching type's full line
    // For C without thorough, only first type's first match clean
    // For C_T, all types all matches clean
    // For NC_T, for each type each match, output full+clean

    // Type order for priority (first match) – we observed Ip before Email for some cases, but to be close to original we will use order: Ip, Email, Url, etc? Let's use help order? Actually help order is Email, Phone, Hash, Ip, Ipv6, Mac, Credit, Url, Files, Bitcoin, Aws, Google, Dns, Social
    // But for "a@b.com 1.2.3.4" -e -i NC, email won (email before ip in help order). So help order makes email first, which matches NC without T for that input (email first). For "1.2.3.4 https://example.com" -i -u NC, help order has Ip before Url (Ip before Url), so Ip wins, which matches observed (Ip won). So help order seems to fit those NC without T cases.
    // For C without T for "a@b.com 1.2.3.4" -e -i, help order Email before Ip, so email wins, which matches observed (email only).
    // For C_T for "a@b.com 1.2.3.4" -e -i, help order Email before Ip would give Email then Ip, but observed Ip then Email. So C_T order is not help order.

    // Let's define two orders:
    // For NC without T and C without T (non-thorough), we use help order.
    // For thorough (both NC_T and C_T), we use order: Ip, Ipv6, Email, Phone, Hash, Credit, Url, Files, Bitcoin, Aws, Google, Social, Mac, Dns? Let's attempt to extract from default C_T all types observed earlier:
    // Default C_T all types (no flags) gave order: Ip, Email, Bitcoin, Files, Credit, Phone, Ipv6, Url, Social, Hash
    // That's: Ip, Email, Bitcoin, Files, Credit, Phone, Ipv6, Url, Social, Hash, (Mac, Aws, Google, Dns missing? Actually Mac was there as part of Ipv6? We had Mac? In that output we had Ipv6 for ::1 and 00:11:22:33:44:55 (which is actually Mac but matched as Ipv6). So Mac maybe not in that list? Let's re-run default C_T with explicit list to see order including Mac and others.

    // For now, we will for thorough use order: Ip, Ipv6, Mac, Email, Phone, Hash, Credit, Url, Files, Bitcoin, Aws, Google, Social, Dns (help order but with Ip first)

    // Actually we need systematic: Let's define ordered types as vector of (type_name, extraction_fn)
    // For non-thorough, iterate in help order and stop after first type that has matches.
    // For thorough, iterate in thorough_order and collect all.

    // Define help order list:
    let help_order: Vec<(&'static str, fn(&str,bool)->Vec<String>)> = vec![
        ("email", find_email as fn(&str,bool)->Vec<String>),
        ("phone_number", |s,t| { find_phone(s,t).into_iter().map(|(c,_f)| c).collect() }),
        ("hashes", find_hash),
        ("ip_address", find_ip),
        ("ipv6_address", find_ipv6),
        ("mac_address", find_mac),
        ("credit_card", find_credit),
        ("url", find_url),
        ("files", find_files),
        ("bitcoin_wallet", find_btc),
        ("aws_keys", find_aws),
        ("google", find_google),
        ("dns", |_s,_t| Vec::new()),
        ("social_security", find_ssn),
    ];

    // For thorough, we could use same order but we observed different order for C_T ip before email (ip is 4th in help order, email 1st). So help order would give email before ip, but observed ip before email. So thorough order is different: Ip before Email.

    // Let's define thorough order as: Ip, Ipv6, Mac, Email, Phone, Hash, Credit, Url, Files, Bitcoin, Aws, Google, Social, Dns
    let thorough_order: Vec<(&'static str, fn(&str,bool)->Vec<String>)> = vec![
        ("ip_address", find_ip),
        ("ipv6_address", find_ipv6),
        ("mac_address", find_mac),
        ("email", find_email),
        ("phone_number", |s,t| { find_phone(s,t).into_iter().map(|(c,_)| c).collect() }),
        ("hashes", find_hash),
        ("credit_card", find_credit),
        ("url", find_url),
        ("files", find_files),
        ("bitcoin_wallet", find_btc),
        ("aws_keys", find_aws),
        ("google", find_google),
        ("social_security", find_ssn),
        ("dns", |_s,_t| Vec::new()),
    ];

    // But we also need phone full vs clean distinction. For phone, we have separate clean/full handling.

    // For clean mode:
    if cli.clean {
        if cli.thorough {
            // C_T
            for (typ, func) in thorough_order.iter() {
                let enabled = match *typ {
                    "email" => cli.email || all,
                    "phone_number" => cli.phone || all,
                    "hashes" => cli.hash || all,
                    "ip_address" => cli.ip_addr || all,
