fn find_credit(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for m in CREDIT_RE.find_iter(line) {
        let s=m.as_str().to_string();
        let digits: String=s.chars().filter(|c| c.is_ascii_digit()).collect();
        if digits.len()==16 { v.push(s.trim().to_string()); if !thorough {break;} }
    }
    v
}
fn find_hash(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in HASH_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_btc(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in BTC_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_aws(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in AWS_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_google(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in GOOGLE_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }
fn find_files(line: &str, thorough: bool) -> Vec<String> {
    let mut v=Vec::new();
    for cap in FILE_RE.captures_iter(line) {
        if let Some(g)=cap.get(1) { v.push(g.as_str().to_string()); } else if let Some(g)=cap.get(0) { v.push(g.as_str().to_string()); }
        if !thorough {break;}
    }
    v
}
fn find_ssn(line: &str, thorough: bool) -> Vec<String> { let mut v=Vec::new(); for m in SSN_RE.find_iter(line) { v.push(m.as_str().to_string()); if !thorough {break;} } v }

#[derive(Debug)]
struct OutputItem {
    typ: &'static str,
    data: String,
    file_path: String,
    line_num: usize,
}

enum PromptResult { Yes, No, Invalid }

fn read_prompt(lines: &Vec<String>, pos: &mut usize) -> PromptResult {
    if *pos >= lines.len() {
        let mut s = String::new();
        let read = io::stdin().read_line(&mut s);
        match read {
            Ok(0) => return PromptResult::Invalid,
            Ok(_) => {
                let t = s.trim();
                if t=="y" { return PromptResult::Yes; }
                else if t=="n" { return PromptResult::No; }
                else { return PromptResult::Invalid; }
            }
            Err(_) => return PromptResult::Invalid,
        }
    }
    let line = lines[*pos].trim().to_string();
    *pos+=1;
    if line=="y" { PromptResult::Yes }
    else if line=="n" { PromptResult::No }
    else { PromptResult::Invalid }
}

fn handle_invalid_for_list(ppath: &Path, lines: &mut Vec<String>, pos: &mut usize) -> ! {
    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
    print!("[+] Do you want to exit? (y/n): ");
    io::stdout().flush().unwrap();
    let mut attempt=0;
    loop {
        let res = read_prompt(lines, pos);
        match res {
            PromptResult::Yes => std::process::exit(1),
            PromptResult::No => {
                if attempt==0 {
                    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                    print!("[+] Do you want to exit? (y/n): ");
                    io::stdout().flush().unwrap();
                    attempt+=1;
                    continue;
                } else {
                    println!("No plugins found. Plugin File: {}", ppath.display());
                    std::process::exit(1);
                }
            }
            PromptResult::Invalid => {
                println!("[-] Invalid input. Please enter 'y' or 'n'.");
                print!("[+] Do you want to exit? (y/n): ");
                io::stdout().flush().unwrap();
                if *pos>=lines.len() {
                    // cause stack overflow
                    fn overflow() { overflow() }
                    overflow();
                }
                continue;
            }
        }
    }
}

fn handle_invalid_for_mod(lines: &mut Vec<String>, pos: &mut usize) -> ! {
    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
    print!("[+] Do you want to exit? (y/n): ");
