                                        }
                                    }
                                }
                            }
                        } else {
                            handle_invalid_for_mod(&mut stdin_lines_vec, &mut prompt_pos);
                        }
                    }
                    Err(_) => { handle_invalid_for_mod(&mut stdin_lines_vec, &mut prompt_pos); }
                }
            }
            Err(_) => {
                if upd!="all" {
                    println!("[-] Error: No existing plugin found with the given URL: {}", upd);
                }
                std::process::exit(1);
            }
        }
    }

