                    print!("[+] Do you want to exit? (y/n): ");
                    io::stdout().flush().unwrap();
                    attempt+=1;
                    continue;
                } else {
                    std::process::exit(1);
                }
            }
            PromptResult::Invalid => {
                println!("[-] Invalid input. Please enter 'y' or 'n'.");
                print!("[+] Do you want to exit? (y/n): ");
                io::stdout().flush().unwrap();
                if *pos>=lines.len() {
                    fn overflow() { overflow() }
                    overflow();
                }
                continue;
            }
        }
    }
}

fn format_output(r: &OutputItem, cli: &Cli) -> String {
    if cli.hide {
        if cli.display {
            if cli.line {
                format!("file: {} {}, line: {}", r.file_path, r.data, r.line_num)
            } else {
                format!("file: {} {}", r.file_path, r.data)
            }
        } else {
            if cli.line {
                format!("{}, line: {}", r.data, r.line_num)
            } else {
                format!("{}", r.data)
            }
        }
    } else {
        if cli.display {
            if cli.line {
                format!("{}, file: {} {}, line: {}", r.typ, r.file_path, r.data, r.line_num)
            } else {
                format!("{}, file: {} {}", r.typ, r.file_path, r.data)
            }
        } else {
            if cli.line {
                format!("{}, {}, line: {}", r.typ, r.data, r.line_num)
            } else {
                format!("{}: {}", r.typ, r.data)
            }
        }
    }
}

fn process_line(line: &str, line_num: usize, file_path: &str, cli: &Cli, filter_re: Option<&Regex>, drop_re: Option<&Regex>) -> Vec<OutputItem> {
    let mut results = Vec::new();
    let any_flag = cli.email || cli.phone || cli.hash || cli.ip_addr || cli.ipv6_addr || cli.mac_addr || cli.credit_card || cli.url || cli.files || cli.bitcoin || cli.aws || cli.google || cli.dns || cli.social;
    let all = !any_flag;

    // help order for non-thorough
    let help_order: Vec<(&'static str, Box<dyn Fn(&str,bool)->Vec<String>>)> = vec![
        ("email", Box::new(|s,t| find_email(s,t))),
        ("phone_number", Box::new(|s,t| find_phone(s,t).into_iter().map(|(c,_)| c).collect())),
        ("hashes", Box::new(|s,t| find_hash(s,t))),
        ("ip_address", Box::new(|s,t| find_ip(s,t))),
        ("ipv6_address", Box::new(|s,t| find_ipv6(s,t))),
        ("mac_address", Box::new(|s,t| find_mac(s,t))),
        ("credit_card", Box::new(|s,t| find_credit(s,t))),
        ("url", Box::new(|s,t| find_url(s,t))),
        ("files", Box::new(|s,t| find_files(s,t))),
        ("bitcoin_wallet", Box::new(|s,t| find_btc(s,t))),
        ("aws_keys", Box::new(|s,t| find_aws(s,t))),
        ("google", Box::new(|s,t| find_google(s,t))),
        ("dns", Box::new(|_s,_t| Vec::new())),
        ("social_security", Box::new(|s,t| find_ssn(s,t))),
    ];

    let thorough_order: Vec<(&'static str, Box<dyn Fn(&str,bool)->Vec<String>>)> = vec![
        ("ip_address", Box::new(|s,t| find_ip(s,t))),
        ("ipv6_address", Box::new(|s,t| find_ipv6(s,t))),
        ("mac_address", Box::new(|s,t| find_mac(s,t))),
        ("email", Box::new(|s,t| find_email(s,t))),
        ("phone_number", Box::new(|s,t| find_phone(s,t).into_iter().map(|(c,_)| c).collect())),
        ("hashes", Box::new(|s,t| find_hash(s,t))),
        ("credit_card", Box::new(|s,t| find_credit(s,t))),
        ("url", Box::new(|s,t| find_url(s,t))),
        ("files", Box::new(|s,t| find_files(s,t))),
        ("bitcoin_wallet", Box::new(|s,t| find_btc(s,t))),
        ("aws_keys", Box::new(|s,t| find_aws(s,t))),
        ("google", Box::new(|s,t| find_google(s,t))),
        ("social_security", Box::new(|s,t| find_ssn(s,t))),
        ("dns", Box::new(|_s,_t| Vec::new())),
    ];

    if cli.clean {
        if cli.thorough {
            for (typ, func) in thorough_order.iter() {
                let enabled = match *typ {
                    "email" => cli.email || all,
                    "phone_number" => cli.phone || all,
                    "hashes" => cli.hash || all,
                    "ip_address" => cli.ip_addr || all,
                    "ipv6_address" => cli.ipv6_addr || all,
                    "mac_address" => cli.mac_addr || all,
                    "credit_card" => cli.credit_card || all,
                    "url" => cli.url || all,
                    "files" => cli.files || all,
                    "bitcoin_wallet" => cli.bitcoin || all,
                    "aws_keys" => cli.aws || all,
                    "google" => cli.google || all,
                    "dns" => cli.dns || all,
                    "social_security" => cli.social || all,
                    _ => false,
                };
                if !enabled { continue; }
                let matches = func(line, true);
                for m in matches {
                    if let Some(f)=filter_re { if !f.is_match(&m) { continue; } }
                    if let Some(d)=drop_re { if d.is_match(&m) { continue; } }
                    results.push(OutputItem { typ: *typ, data: m, file_path: file_path.to_string(), line_num });
                }
            }
        } else {
            for (typ, func) in help_order.iter() {
                let enabled = match *typ {
                    "email" => cli.email || all,
                    "phone_number" => cli.phone || all,
                    "hashes" => cli.hash || all,
                    "ip_address" => cli.ip_addr || all,
                    "ipv6_address" => cli.ipv6_addr || all,
                    "mac_address" => cli.mac_addr || all,
                    "credit_card" => cli.credit_card || all,
                    "url" => cli.url || all,
                    "files" => cli.files || all,
                    "bitcoin_wallet" => cli.bitcoin || all,
                    "aws_keys" => cli.aws || all,
                    "google" => cli.google || all,
                    "dns" => cli.dns || all,
                    "social_security" => cli.social || all,
                    _ => false,
                };
                if !enabled { continue; }
                let matches = func(line, false);
                for m in matches {
                    if let Some(f)=filter_re { if !f.is_match(&m) { continue; } }
                    if let Some(d)=drop_re { if d.is_match(&m) { continue; } }
                    results.push(OutputItem { typ: *typ, data: m, file_path: file_path.to_string(), line_num });
                    break;
                }
                if !results.is_empty() { break; }
            }
        }
    } else {
        // non-clean
        if let Some(f)=filter_re { if !f.is_match(line) { return results; } }
        let line_matches_drop = if let Some(d)=drop_re { d.is_match(line) } else { false };

        if cli.thorough {
            for (typ, func) in thorough_order.iter() {
                let enabled = match *typ {
                    "email" => cli.email || all,
                    "phone_number" => cli.phone || all,
                    "hashes" => cli.hash || all,
                    "ip_address" => cli.ip_addr || all,
                    "ipv6_address" => cli.ipv6_addr || all,
                    "mac_address" => cli.mac_addr || all,
                    "credit_card" => cli.credit_card || all,
                    "url" => cli.url || all,
                    "files" => cli.files || all,
                    "bitcoin_wallet" => cli.bitcoin || all,
                    "aws_keys" => cli.aws || all,
                    "google" => cli.google || all,
                    "dns" => cli.dns || all,
                    "social_security" => cli.social || all,
                    _ => false,
                };
                if !enabled { continue; }
                if *typ=="phone_number" {
                    let matches = find_phone(line, true);
                    for (clean, full) in matches {
                        if let Some(d)=drop_re { if d.is_match(&clean) { continue; } }
                        if line_matches_drop {
                            results.push(OutputItem { typ: *typ, data: clean, file_path: file_path.to_string(), line_num });
                        } else {
                            results.push(OutputItem { typ: *typ, data: line.to_string(), file_path: file_path.to_string(), line_num });
                            results.push(OutputItem { typ: *typ, data: clean, file_path: file_path.to_string(), line_num });
                        }
                    }
                } else {
                    let matches = func(line, true);
                    for m in matches {
                        if let Some(d)=drop_re { if d.is_match(&m) { continue; } }
                        if line_matches_drop {
                            results.push(OutputItem { typ: *typ, data: m, file_path: file_path.to_string(), line_num });
                        } else {
                            results.push(OutputItem { typ: *typ, data: line.to_string(), file_path: file_path.to_string(), line_num });
                            results.push(OutputItem { typ: *typ, data: m, file_path: file_path.to_string(), line_num });
                        }
                    }
                }
            }
        } else {
            if line_matches_drop {
                for (typ, func) in help_order.iter() {
                    let enabled = match *typ {
                        "email" => cli.email || all,
                        "phone_number" => cli.phone || all,
                        "hashes" => cli.hash || all,
                        "ip_address" => cli.ip_addr || all,
                        "ipv6_address" => cli.ipv6_addr || all,
                        "mac_address" => cli.mac_addr || all,
                        "credit_card" => cli.credit_card || all,
                        "url" => cli.url || all,
                        "files" => cli.files || all,
                        "bitcoin_wallet" => cli.bitcoin || all,
                        "aws_keys" => cli.aws || all,
                        "google" => cli.google || all,
                        "dns" => cli.dns || all,
                        "social_security" => cli.social || all,
                        _ => false,
                    };
                    if !enabled { continue; }
                    if *typ=="phone_number" {
                        let matches=find_phone(line,false);
                        for (clean,_) in matches {
                            if let Some(d)=drop_re { if d.is_match(&clean) { continue; } }
                            results.push(OutputItem { typ: *typ, data: clean, file_path: file_path.to_string(), line_num });
                            break;
                        }
                    } else {
                        let matches=func(line,false);
                        for m in matches {
                            if let Some(d)=drop_re { if d.is_match(&m) { continue; } }
                            results.push(OutputItem { typ: *typ, data: m, file_path: file_path.to_string(), line_num });
                            break;
                        }
                    }
                    if !results.is_empty() { break; }
                }
            } else {
                for (typ, func) in help_order.iter() {
                    let enabled = match *typ {
                        "email" => cli.email || all,
                        "phone_number" => cli.phone || all,
                        "hashes" => cli.hash || all,
                        "ip_address" => cli.ip_addr || all,
                        "ipv6_address" => cli.ipv6_addr || all,
                        "mac_address" => cli.mac_addr || all,
                        "credit_card" => cli.credit_card || all,
                        "url" => cli.url || all,
                        "files" => cli.files || all,
                        "bitcoin_wallet" => cli.bitcoin || all,
                        "aws_keys" => cli.aws || all,
                        "google" => cli.google || all,
                        "dns" => cli.dns || all,
                        "social_security" => cli.social || all,
                        _ => false,
                    };
                    if !enabled { continue; }
                    let matches= if *typ=="phone_number" {
                        let pm=find_phone(line,false);
                        if pm.is_empty() { Vec::new() } else { vec!["x".to_string()] }
                    } else {
                        func(line,false)
                    };
                    if !matches.is_empty() {
                        results.push(OutputItem { typ: *typ, data: line.to_string(), file_path: file_path.to_string(), line_num });
                        break;
                    }
                }
            }
        }
    }

    results
}

fn main() {
    let _start = Instant::now();
    let cli = parse_cli();
    let ppath = plugin_path();

    // read all stdin lines upfront for prompt handling
    // We read stdin regardless, because for extraction we need it, and for plugin commands prompt reading also uses stdin
    let mut stdin_lines_vec: Vec<String> = Vec::new();
    {
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            if let Ok(l)=line { stdin_lines_vec.push(l); }
        }
    }
    let mut prompt_pos = 0usize;
    let mut file_missing_startup = false;

    match fs::read_to_string(&ppath) {
        Ok(_) => {},
        Err(_) => {
            file_missing_startup = true;
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", ppath.display());
        }
    }

    if cli.help {
        println!("{}", HELP_TEXT);
        return;
    }
    if cli.version {
        println!("DataSurgeon: https://github.com/Drew-Alleman/DataSurgeon {}", VERSION);
        return;
    }

    if cli.list {
        if file_missing_startup {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", ppath.display());
            println!("No plugins found. Plugin File: {}", ppath.display());
            std::process::exit(1);
        }
        match fs::read_to_string(&ppath) {
            Ok(content) => {
                match serde_json::from_str::<serde_json::Value>(&content) {
                    Ok(v) => {
                        if let Some(arr)=v.as_array() {
                            if arr.is_empty() {
                                println!("No plugins found. Plugin File: {}", ppath.display());
